require 'json'; m=Sketchup.active_model; volg=%w[Pad Plein Plateau Helling Trap Brug Vloer Blok Vulstuk Pilaren Toren Raster Gebouw Vak Deel Steeg Tunnel Vlonder Fietspad]; r=->(v){ (v.to_m*100).round/100.0 }; kl=->(mat){ mat ? (c=mat.color; '#%02x%02x%02x' % [c.red,c.green,c.blue]) : nil }; walk=nil; walk=->(ents,t,mat,top,pts){ ents.each{|e|; if e.is_a?(Sketchup::Face) then ma=e.material||mat; n=e.normal.transform(t); e.outer_loop.vertices.each{|v| p=v.position.transform(t); pts << [r.(p.x),r.(p.y),r.(p.z)]}; if n.z>0.2 then top << {'p'=>e.outer_loop.vertices.map{|v| p=v.position.transform(t); [r.(p.x),r.(p.y),r.(p.z)]}, 'c'=>kl.(ma)} end; elsif e.is_a?(Sketchup::Group)||e.is_a?(Sketchup::ComponentInstance) then walk.(e.definition.entities, t*e.transformation, e.material||mat, top, pts) end }}; out=[]; m.definitions.each{|d| next if d.image? || d.name=~/^(Hulp|Schaalfiguur)/; cat=d.name.split(' ').first; next unless volg.include?(cat); top=[]; pts=[]; walk.(d.entities, Geom::Transformation.new, nil, top, pts); b=d.bounds; out << {'naam'=>d.name, 'soort'=>cat, 'bron'=>(d.description.start_with?('Raatstad padblok') ? 'nieuw' : 'concept'), 'groep'=>d.group?, 'bb'=>[r.(b.min.x),r.(b.min.y),r.(b.min.z),r.(b.max.x),r.(b.max.y),r.(b.max.z)], 'boven'=>top, 'punten'=>pts.uniq}}; f='G:/Mijn Drive/Projecten/hexgrid city concept/raatstad-modules.json'; File.write(f, JSON.generate({'bestand'=>m.path, 'modules'=>out})); puts "export: #{out.size} modules, #{File.size(f)} bytes"
